#!/usr/bin/env node

// Fails if src/content/docs/ has been committed directly instead of
// being generated by sync-docs.mjs. Run in CI after sync-docs to
// verify the output matches what's checked in (if anything is).

import { execSync } from 'node:child_process'

const status = execSync('git status --porcelain website/src/content/docs/', {
  encoding: 'utf-8',
  cwd: new URL('../..', import.meta.url).pathname,
}).trim()

if (status) {
  console.error('docs-freshness: src/content/docs/ has uncommitted changes after sync.')
  console.error('This means the checked-in docs are out of sync with docs/.')
  console.error('Run `cd website && npm run sync-docs` and commit the result,')
  console.error('or (preferred) ensure src/content/docs/ is in .gitignore.\n')
  console.error(status)
  process.exit(1)
} else {
  console.log('docs-freshness: src/content/docs/ is clean after sync.')
}
